import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { tagList } from '../claims/useClaims';
import { usePersonAction } from './usePersonAction';
import { GRADES, peopleKey, type Person } from './usePeople';

// The row's grade select and its save: records the chosen grade from the sheet's today exactly as
// the person form would (the person's other values as the row loaded them, with the version it
// loaded, so a save over someone else's newer save is refused). Saving the grade the row shows
// records nothing. A refusal shows the person's error.
export function InlineGrade({ person, shown }: { person: Person; shown: string }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [grade, setGrade] = useState(shown);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  useEffect(() => setGrade(shown), [shown, person.version]);

  const save = useMutation({
    mutationFn: (chosen: string) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${encodeURIComponent(person.id)}`, {
        name: person.name,
        grade: chosen,
        gradeFrom: '',
        terms: person.baseTerms,
        contact: person.contact,
        tags: tagList(person.tags),
        user,
        version: person.version,
      }),
    onSuccess: () => {
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
  });
  const taken = usePersonAction(person.id, () => save.reset());

  return (
    <>
      <select
        data-testid="person-inline-grade"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value);
          save.reset();
        }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>{g}</option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-inline-grade-save"
        onClick={() => {
          taken();
          once(() => save.mutateAsync(grade));
        }}
      >
        Save grade
      </button>
      {save.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          The grade could not be saved.
        </span>
      )}
    </>
  );
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Takes the imported lines in order. A line whose name is a person's name or alias on the sheet (as names
 * are compared) updates that person as the person form saves them: the grade is recorded from the sheet's
 * today (nothing when it is the grade they have), the terms and contact are set when the line gives them,
 * audited as PERSON_EDITED with the figures it moved. Any other line adds a person as the person form adds
 * them (PERSON_ADDED, then the figures it moved). Every line is checked against the sheet first (an added
 * name clashes with no one's name or alias, a contact with no one else's contact, no person is named by two
 * lines), so one refused line writes nothing.
 */
public class SaveImportPeople {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidImportPeople request, People people, Audit audit,
            Rollup rollup, ObjectResponse<ImportPeopleResponse> response) throws InvalidPersonException, PersonConflictException {
        List<Person> matched = new ArrayList<>();
        Set<Long> updating = new HashSet<>();
        int number = 0;
        for (PersonRequest line : request.people()) {
            number++;
            Person person = people.findByName(sheetId, line.name());
            if (person == null) {
                if (people.nameTaken(sheetId, line.name(), null)) {
                    throw new InvalidPersonException("Person " + number + ": the name is already in use");
                }
            } else if (!updating.add(person.getId())) {
                throw new InvalidPersonException("Person " + number + ": " + person.getName() + " is named twice in the import");
            }
            if (!line.contact().isEmpty()
                    && people.contactTaken(sheetId, line.contact(), person == null ? null : person.getId())) {
                throw new InvalidPersonException("Person " + number + ": the contact is already in use");
            }
            matched.add(person);
        }
        int added = 0;
        int updated = 0;
        for (int i = 0; i < request.people().size(); i++) {
            PersonRequest line = request.people().get(i);
            Person person = matched.get(i);
            RollupFigures before = rollup.figures(sheetId);
            if (person == null) {
                person = people.add(sheetId, line.name(), line.grade(),
                        line.terms().isEmpty() ? null : Integer.valueOf(line.terms()),
                        line.contact().isEmpty() ? null : line.contact());
                audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                        + " name=" + person.getName() + " grade=" + person.getGrade()
                        + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                        + (person.getContact() == null ? "" : " contact=" + person.getContact()));
                added++;
            } else {
                if (!line.terms().isEmpty()) {
                    person.editTerms(Integer.valueOf(line.terms()));
                }
                if (!line.contact().isEmpty()) {
                    person.editContact(line.contact());
                }
                if (!line.grade().equals(person.getGrade())) {
                    person.recordGrade(person.getToday(), line.grade());
                }
                if (!people.save(person)) {
                    throw new PersonConflictException(person.getId());
                }
                audit.recordOnCommit("PERSON_EDITED sheet=" + sheetId + " by=" + request.user()
                        + " name=" + person.getName() + " grade=" + person.getGrade()
                        + (person.isTermsChanged() ? " terms=" + (person.getTermsShown() == null ? "" : person.getTermsShown()) : "")
                        + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
                updated++;
            }
            rollup.recordChanges(sheetId, request.user(), before);
        }
        response.send(new ImportPeopleResponse(added, updated));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePersonCreated {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, People people, Audit audit, @Val RollupFigures before, Rollup rollup,
            ObjectResponse<ResponseEntity<PersonResponse>> response) throws InvalidPersonException {
        if (people.nameTaken(sheetId, request.name(), null)) {
            throw new InvalidPersonException("The name is already in use");
        }
        if (!request.contact().isEmpty() && people.contactTaken(sheetId, request.contact(), null)) {
            throw new InvalidPersonException("The contact is already in use");
        }
        Person person = people.add(sheetId, request.name(), request.grade(),
                request.terms().isEmpty() ? null : Integer.valueOf(request.terms()),
                request.contact().isEmpty() ? null : request.contact(),
                request.tags().isEmpty() ? null : request.tags());
        audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                + " name=" + person.getName() + " grade=" + person.getGrade()
                + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                + (person.getContact() == null ? "" : " contact=" + person.getContact()));
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(PersonResponse.from(person), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a bulk grade the person form would refuse for every person: an unknown grade or a from-date
 *  that is not a date (or an archived sheet). A viewer changes nothing: their bulk grade grades no one. */
public class ValidateBulkGrade {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody BulkGradeRequest request,
            Out<BulkGradeRequest> body, Settings settings) throws InvalidPersonException, ViewerRefusedException {
        boolean viewer = false;
        try {
            settings.refuseViewer(sheetId, request.user());
        } catch (ViewerRefusedException e) {
            viewer = true;
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                java.time.LocalDate.parse(gradeFrom);
            } catch (java.time.format.DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date");
            }
        }
        body.set(new BulkGradeRequest(viewer || request.personIds() == null ? List.of() : request.personIds(), grade, gradeFrom, request.user()));
    }
}

